import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:pocketdesk_app/address.dart';
import 'package:pocketdesk_app/main.dart';

void main() {
  test('normalizeLink accepts https links and bare hosts, rejects http/garbage', () {
    expect(normalizeLink('https://a.b.com/#c=ABC'), 'https://a.b.com/#c=ABC');
    expect(normalizeLink('a.b.com'), 'https://a.b.com');
    expect(normalizeLink('http://a.b.com'), isNull);
    expect(normalizeLink(''), isNull);
  });

  // Vector generated by the agent (Python crypto.addr_mac) — signatures must match across languages.
  const keyHex = '6b82f2982e0fc8803cb924173aa194d678bbd8ea09ed10614b5ccd0074ebbd9a';
  test('address MAC matches the Python agent', () {
    expect(addrMac(keyHex, 'https://x.serveousercontent.com', 1000), _pyMac);
  });

  test('pickAddress follows only validly signed, fresh announcements (newest first)', () {
    final pcs = [{'deviceId': 'd_1', 'keyHex': keyHex}];
    String ev(String url, int ts, String dev, String mac) => jsonEncode({'event': 'message', 'message': jsonEncode({'u': url, 'ts': ts, 'm': {dev: mac}})});
    final good = ev('https://new.example', 1000, 'd_1', addrMac(keyHex, 'https://new.example', 1000));
    final old = ev('https://old.example', 900, 'd_1', addrMac(keyHex, 'https://old.example', 900));
    final forged = ev('https://evil.example', 1001, 'd_1', 'ab' * 32);
    final wrongDev = ev('https://other.example', 1002, 'd_9', addrMac(keyHex, 'https://other.example', 1002));
    expect(pickAddress(pcs, [old, good].join('\n'), nowSeconds: 1500), 'https://new.example');
    expect(pickAddress(pcs, [good, forged, wrongDev].join('\n'), nowSeconds: 1500), 'https://new.example'); // forgeries skipped
    expect(pickAddress(pcs, [forged].join('\n'), nowSeconds: 1500), isNull);
    expect(pickAddress(pcs, good, nowSeconds: 1000 + 8 * 24 * 3600), isNull); // too old
    expect(pickAddress(pcs, ev('http://insecure.example', 1000, 'd_1', addrMac(keyHex, 'http://insecure.example', 1000)), nowSeconds: 1500), isNull);
  });
}

const _pyMac = 'f1765140898486f948312f673118dba1ca1c0266c637ac9968208472bb90864a';
